        author = thread.created_by
        cohort_id = None
        if author is not None and not (author.role == "admin" or author.is_staff):
            enrollments = Enrollment.objects.filter(user_id=author.pk, status__in=posted_as)
            cohort_id = (
                enrollments.filter(cohort__start_date__lte=posted_on, cohort__end_date__gte=posted_on)
                .order_by("-cohort__start_date", "-pk")
                .values_list("cohort_id", flat=True)
                .first()
            ) or enrollments.order_by("-enrolled_at", "-pk").values_list("cohort_id", flat=True).first()
        if cohort_id is None:
            cohort_id = (
                Cohort.objects.filter(start_date__lte=posted_on, end_date__gte=posted_on)
                .order_by("-start_date", "-pk")
                .values_list("pk", flat=True)
                .first()
            )
        if cohort_id is not None:
            ForumThread.objects.filter(pk=thread.pk).update(cohort_id=cohort_id)


